"""Writes tools/stats/cases_t10.txt: makedist, fitdist and the probability distribution objects."""
import os
here = os.path.dirname(os.path.abspath(__file__))
PRE = ("dn=abs(x(1:50)')+0.1; db=(x(1:40)'+2)/4; dp=[0 1 3 2 5 0 7 4 2 9 1 3 6 2 4 8 0 1 5 3 2 4 6 1 0 2 3 5 7 2]'; dx=x(1:50)'; ")
L = ["# generated by make_t10_cases.py"]
def add(cs, fmt):
    for c in cs:
        L.append(fmt.replace("{c}", c))
PROPS = "{pd.DistributionName, pd.NumParameters, pd.ParameterNames, pd.ParameterDescription, pd.ParameterValues, pd.Truncation, pd.IsTruncated, pd.ParameterCovariance, pd.ParameterIsFixed}"
INPUT = "{pd.InputData.data, pd.InputData.cens, pd.InputData.freq}"
makes = ["makedist('Normal')", "makedist('Normal','mu',1,'sigma',2)", "makedist('Lognormal','mu',0.5,'sigma',0.8)", "makedist('Exponential','mu',2)", "makedist('Gamma','a',2,'b',3)", "makedist('Weibull','a',2,'b',1.5)", "makedist('Beta','a',2,'b',3)", "makedist('Uniform','Lower',1,'Upper',4)",
         "makedist('Poisson','lambda',3)", "makedist('Binomial','N',10,'p',0.3)", "makedist('NegativeBinomial','R',3,'p',0.4)", "makedist('Rayleigh','B',1.5)", "makedist('ExtremeValue','mu',0,'sigma',2)", "makedist('GeneralizedExtremeValue','k',0.2,'sigma',1,'mu',0)",
         "makedist('GeneralizedPareto','k',0.2,'sigma',1,'theta',0)", "makedist('normal')", "makedist('Gamma')", "makedist('Weibull')", "makedist('Beta')", "makedist('Uniform')", "makedist('Poisson')", "makedist('Binomial')", "makedist('Exponential')", "makedist('Rayleigh')"]
add(makes, "pd = {c}; r = " + PROPS + ";")
fits = ["fitdist(dx,'Normal')", "fitdist(dn,'Lognormal')", "fitdist(dn,'Exponential')", "fitdist(dn,'Gamma')", "fitdist(dn,'Weibull')", "fitdist(db,'Beta')", "fitdist(dn,'Rayleigh')", "fitdist(dp,'Poisson')", "fitdist(dx,'ExtremeValue')", "fitdist(dn,'Uniform')", "fitdist(dp,'NegativeBinomial')", "fitdist(dp,'Binomial','NTrials',12)", "fitdist(dn,'normal')"]
add(fits, "pd = {c}; r = " + PROPS + ";")
add(fits[:3], "pd = {c}; r = " + INPUT + ";")
add(["fitdist(dn,'Gamma','Alpha',0.1)", "fitdist(dn,'Normal','Frequency',(1:50)')", "fitdist(dn,'Normal','Censoring',double(dn>1.2))", "fitdist(dn,'Weibull','Censoring',double(dn>1.2))", "fitdist(dn,'Exponential','Frequency',(1:50)')", "fitdist([dn;NaN],'Normal')"], "pd = {c}; r = " + PROPS + ";")
meths = ["mean(pd)", "var(pd)", "std(pd)", "median(pd)", "iqr(pd)", "pdf(pd,[0.2 0.5 1 2])", "cdf(pd,[0.2 0.5 1 2])", "icdf(pd,[0.1 0.5 0.9])", "negloglik(pd)", "paramci(pd)", "paramci(pd,'Alpha',0.1)", "cdf(pd,[0.2 1],'upper')", "pdf(pd,[])", "icdf(pd,[-1 2])"]
for fam, ctor in [("N", "fitdist(dx,'Normal')"), ("G", "fitdist(dn,'Gamma')"), ("W", "fitdist(dn,'Weibull')"), ("E", "fitdist(dn,'Exponential')"), ("L", "fitdist(dn,'Lognormal')"), ("B", "fitdist(db,'Beta')"), ("R", "fitdist(dn,'Rayleigh')")]:
    add(meths, "pd = " + ctor + "; r = {c};")
for ctor in ["makedist('Normal','mu',1,'sigma',2)", "makedist('Poisson','lambda',3)", "makedist('Binomial','N',10,'p',0.3)", "makedist('Uniform','Lower',1,'Upper',4)", "makedist('GeneralizedExtremeValue','k',0.2,'sigma',1,'mu',0)", "makedist('GeneralizedPareto','k',0.2,'sigma',1,'theta',0)", "makedist('NegativeBinomial','R',3,'p',0.4)", "makedist('ExtremeValue','mu',0,'sigma',2)"]:
    add(["mean(pd)", "var(pd)", "std(pd)", "median(pd)", "iqr(pd)", "pdf(pd,[0 1 2 3])", "cdf(pd,[0 1 2 3])", "icdf(pd,[0.1 0.5 0.9])"], "pd = " + ctor + "; r = {c};")
add(["truncate(pd,0.5,3)", "truncate(pd,-1,1)", "truncate(pd,1,0)"], "pd = makedist('Normal','mu',1,'sigma',2); pt = {c}; r = {pt.Truncation, pt.IsTruncated, pdf(pt,[0 1 2 3]), cdf(pt,[0 1 2 3]), icdf(pt,[0.1 0.5 0.9]), mean(pt), var(pt), median(pt)};")
add(["makedist('Foo')", "makedist()", "makedist('Normal','mu',1,'foo',2)", "makedist('Normal','sigma',-1)", "makedist('Gamma','a',-1)", "makedist('Uniform','Lower',3,'Upper',1)", "makedist('Binomial','N',2.5)", "makedist('Binomial','p',2)", "makedist('Normal','mu')", "fitdist()", "fitdist(dn)", "fitdist(dn,'Foo')", "fitdist(dn,'Beta')", "fitdist(-dn,'Gamma')", "fitdist(dn,'Poisson')", "fitdist([],'Normal')", "fitdist(dn,'Normal','Foo',1)", "fitdist(dp,'Binomial')", "fitdist(dn,'Normal','Frequency',(1:5)')"], "pd = {c}; r = 1;")
L = [L[0]] + [PRE + l for l in L[1:]]
with open(os.path.join(here, "cases_t10.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(L) + "\n")
print(len(L))
